-- Número
INSERT INTO public.edition_issues (slug, number, period_start, period_label, title, cover_line, cover_image_id, cover_article_slug, research_closed_at, plan, status)
VALUES ($edi$n01-noviembre-2026$edi$, 1, $edi$2026-11-01$edi$::date, $edi${"es":"Noviembre 2026","en":"November 2026"}$edi$::jsonb, $edi${"es":"La ciudad acelera","en":"The city accelerates"}$edi$::jsonb, $edi${"es":"Fórmula 1 y Día de Muertos en el mismo fin de semana · Mérida en el mapa de la guía · Mónaco después del Yacht Show","en":"Formula 1 and Day of the Dead on the same weekend · Mérida on the guide's map · Monaco after the Yacht Show"}$edi$::jsonb, (SELECT id FROM public.edition_images WHERE key = $edi$img_cdmx_angel_noche$edi$), $edi$cdmx-fin-de-semana-gran-premio$edi$, $edi$2026-10-22$edi$::date, $edi${"frequency":{"es":"Revista mensual. The World Brief se actualiza solo cuando hay fuentes nuevas verificadas; las oportunidades se actualizan según su vigencia, sin que eso cuente como número nuevo.","en":"Monthly magazine. The World Brief is updated only when there are new verified sources; opportunities are updated by validity, which does not count as a new issue."},"pillars":[{"es":"Portada: un acontecimiento con fecha cierta y acción real para el miembro (Gran Premio de la Ciudad de México).","en":"Cover: a dated event with a real action for the member (Mexico City Grand Prix)."},{"es":"Reportajes: gastronomía y hoteles (Mérida y Guadalajara tras la Guía MICHELIN), náutica (Monaco Yacht Show).","en":"Features: dining and hotels (Mérida and Guadalajara after the MICHELIN Guide), yachting (Monaco Yacht Show)."},{"es":"Breves con agenda: relojería (Watches and Wonders 2027), arte (Art Basel Miami Beach), golf (PGA Tour en Los Cabos).","en":"Short pieces with dates: watchmaking (Watches and Wonders 2027), art (Art Basel Miami Beach), golf (PGA Tour in Los Cabos)."},{"es":"Explicadores (información, no asesoría): tasas del Banco de México; calendario europeo de la IA de alto riesgo.","en":"Explainers (information, not advice): Bank of Mexico rates; Europe's high-risk AI calendar."},{"es":"The World Brief: seis hechos fechados con fuente primaria y corroboración.","en":"The World Brief: six dated facts with a primary source and corroboration."}],"not_covered":{"es":"Este número no tiene todavía piezas de moda, belleza, superautos, aviación privada ni bienestar: preferimos un tema vacío a un texto sin fuentes. Quien los elija verá un aviso honesto en Mi Edición.","en":"This issue has no fashion, beauty, supercars, private aviation or wellness pieces yet: we prefer an empty topic to an unsourced text. Members who choose them will see an honest notice in My Edition."},"workflow":{"es":"Investigación → fuentes → borrador asistido por IA → verificación → revisión editorial → maquetación → publicación. La IA redacta; no es autoridad factual.","en":"Research → sources → AI-assisted draft → verification → editorial review → layout → publication. AI drafts; it is not a factual authority."}}$edi$::jsonb, 'pending_review')
ON CONFLICT (slug) DO NOTHING;

-- Artículos (borradores asistidos por IA, pendientes de revisión)
INSERT INTO public.edition_articles (issue_id, slug, section, format, topics, kicker, title, dek, byline, hero_image_id, fact_status, sensitive, fact_date, valid_until, destinations, body, actions, sort_order, drafted_by, status)
VALUES ((SELECT id FROM public.edition_issues WHERE slug = $edi$n01-noviembre-2026$edi$), $edi$carta-del-editor-n01$edi$, $edi$carta$edi$, $edi$letter$edi$, ARRAY[]::text[], $edi${"es":"Carta del editor","en":"Editor's letter"}$edi$::jsonb, $edi${"es":"Una revista que se puede comprobar","en":"A magazine you can check"}$edi$::jsonb, $edi${"es":"Por qué el primer número de The Private Edition trae fechas, fuentes y pocas promesas.","en":"Why the first issue of The Private Edition comes with dates, sources and few promises."}$edi$::jsonb, $edi${"es":"Dirección editorial de IATOS Privé · borrador pendiente de firma","en":"IATOS Privé editorial direction · draft pending signature"}$edi$::jsonb, NULL, $edi$editorial$edi$, false, NULL, NULL, ARRAY[]::text[], $edi$[{"t":"p","es":"Bienvenido al primer número de The Private Edition. Lo pensamos como una revista y no como un feed: tiene portada, índice, reportajes, breves y un cierre. Y tiene una regla que nos impusimos antes de escribir la primera línea: todo lo que afirmamos se puede comprobar.","en":"Welcome to the first issue of The Private Edition. We designed it as a magazine, not a feed: it has a cover, a table of contents, features, short pieces and a closing page. And it has a rule we set before writing the first line: everything we state can be checked."},{"t":"p","es":"Cada texto termina con sus fuentes, la fecha en que las consultamos y lo que tomamos de ellas. Las fotografías llevan crédito y licencia; cuando una imagen es ilustrativa —un yate que no es el yate del que hablamos, un plato que no es de ese restaurante— lo decimos debajo de la foto.","en":"Every story ends with its sources, the date we consulted them and what we took from them. Photographs carry credit and licence; when an image is illustrative —a yacht that is not the yacht we write about, a dish that is not from that restaurant— we say so under the photo."},{"t":"quote","es":"Preferimos una sección vacía a una página sin fuentes.","en":"We would rather have an empty section than a page without sources."},{"t":"p","es":"Los borradores se preparan con ayuda de inteligencia artificial. La IA redacta; no decide qué es verdad. Un editor humano revisa, corrige y aprueba cada pieza antes de que llegue a usted, y si después encontramos un error, la corrección queda visible con su fecha.","en":"Drafts are prepared with the help of artificial intelligence. AI drafts; it does not decide what is true. A human editor reviews, corrects and approves every piece before it reaches you, and if we later find a mistake, the correction stays visible with its date."},{"t":"p","es":"Este número se llama «La ciudad acelera» porque a finales de octubre la Ciudad de México recibe, el mismo fin de semana, a la Fórmula 1 y su desfile de Día de Muertos. También viajamos a Mérida y Guadalajara, que la Guía MICHELIN incorporó este año, y a Mónaco, donde terminó la 35.ª edición del Yacht Show. Cuando una historia puede convertirse en un plan, le ofrecemos el siguiente paso: explorar el destino en Privé, preguntarle a Iato o planear el viaje. Nunca le prometeremos una mesa o un lugar que no hayamos confirmado.","en":"This issue is called 'The city accelerates' because at the end of October Mexico City hosts, on the same weekend, Formula 1 and its Day of the Dead parade. We also travel to Mérida and Guadalajara, which the MICHELIN Guide added this year, and to Monaco, where the 35th Yacht Show has just closed. When a story can become a plan, we offer the next step: explore the destination in Privé, ask Iato or plan the trip. We will never promise you a table or a seat we have not confirmed."},{"t":"p","es":"Su edición es suya: elija temas, ordene secciones, descárguela en PDF o para leer sin conexión en el avión. La revista es la misma para todos los miembros; lo que cambia es la selección y el orden, que usted controla.","en":"Your edition is yours: choose topics, reorder sections, download it as a PDF or for offline reading on the plane. The magazine is the same for every member; what changes is the selection and the order, which you control."}]$edi$::jsonb, $edi$[]$edi$::jsonb, 10, 'claude', 'pending_review')
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.edition_articles (issue_id, slug, section, format, topics, kicker, title, dek, byline, hero_image_id, fact_status, sensitive, fact_date, valid_until, destinations, body, actions, sort_order, drafted_by, status)
VALUES ((SELECT id FROM public.edition_issues WHERE slug = $edi$n01-noviembre-2026$edi$), $edi$cdmx-fin-de-semana-gran-premio$edi$, $edi$portada$edi$, $edi$feature$edi$, ARRAY[$edi$formula_1$edi$, $edi$deportes$edi$, $edi$mexico$edi$, $edi$eventos_internacionales$edi$, $edi$cultura$edi$, $edi$experiencias_extraordinarias$edi$]::text[], $edi${"es":"Portada · Fórmula 1 · México","en":"Cover · Formula 1 · Mexico"}$edi$::jsonb, $edi${"es":"La ciudad acelera","en":"The city accelerates"}$edi$::jsonb, $edi${"es":"Del 30 de octubre al 1 de noviembre, el Gran Premio de la Ciudad de México y el desfile de Día de Muertos comparten fin de semana. Fechas, horarios y traslados, con fuentes oficiales.","en":"From 30 October to 1 November, the Mexico City Grand Prix and the Day of the Dead parade share a weekend. Dates, times and transport, from official sources."}$edi$::jsonb, $edi${"es":"Redacción IATOS Privé","en":"IATOS Privé newsroom"}$edi$::jsonb, (SELECT id FROM public.edition_images WHERE key = $edi$img_cdmx_angel_noche$edi$), $edi$mixed$edi$, false, $edi$2026-10-22$edi$::date, $edi$2026-11-02$edi$::date, ARRAY[$edi$cdmx$edi$]::text[], $edi$[{"t":"p","es":"El calendario oficial de la Fórmula 1 para 2026 sitúa el Gran Premio de la Ciudad de México como la ronda 19 de la temporada: del viernes 30 de octubre al domingo 1 de noviembre, en el Autódromo Hermanos Rodríguez. Llega una semana después del Gran Premio de Estados Unidos (23 al 25 de octubre) y una antes del de São Paulo (6 al 8 de noviembre).","en":"Formula 1's official 2026 calendar places the Mexico City Grand Prix as round 19 of the season: Friday 30 October to Sunday 1 November, at the Autódromo Hermanos Rodríguez. It comes a week after the United States Grand Prix (23–25 October) and a week before São Paulo (6–8 November)."},{"t":"p","es":"El trazado mide 4.304 kilómetros y la carrera se disputa a 71 vueltas, 305.354 kilómetros en total, según la ficha oficial. El récord de vuelta, 1:17.774, es de Valtteri Bottas desde 2021. La altitud explica buena parte de su carácter: el equipo Mercedes la sitúa en unos 2,285 metros sobre el nivel del mar y la describe como la sede más alta que visita en el año.","en":"The track is 4.304 kilometres long and the race runs over 71 laps, 305.354 kilometres in all, according to the official data sheet. The lap record, 1:17.774, has belonged to Valtteri Bottas since 2021. Altitude explains much of its character: the Mercedes team puts it at about 2,285 metres above sea level and describes it as the highest venue it visits all year."},{"t":"facts","title":{"es":"El fin de semana, en hora del centro de México","en":"The weekend, in Central Mexico time"},"items":[{"label":{"es":"Viernes 30 oct","en":"Fri 30 Oct"},"value":{"es":"Práctica 1, 12:30 · Práctica 2, 16:00","en":"Practice 1, 12:30 · Practice 2, 16:00"}},{"label":{"es":"Sábado 31 oct","en":"Sat 31 Oct"},"value":{"es":"Práctica 3, 11:30 · Calificación, 15:00","en":"Practice 3, 11:30 · Qualifying, 15:00"}},{"label":{"es":"Domingo 1 nov","en":"Sun 1 Nov"},"value":{"es":"Carrera, 14:00","en":"Race, 14:00"}},{"label":{"es":"Nota","en":"Note"},"value":{"es":"F1 publica el horario en UTC; la conversión a UTC−6 es nuestra. Confírmelo en la app oficial el día del evento.","en":"F1 publishes times in UTC; the conversion to UTC−6 is ours. Confirm on the official app on the day."}}]},{"t":"h","es":"Cómo llegar sin perder la tarde","en":"Getting there without losing the afternoon"},{"t":"p","es":"La guía oficial del promotor recomienda el transporte público: la Línea 9 del Metro, con las estaciones Velódromo, Ciudad Deportiva y Puebla a poca distancia de las puertas, y la Línea 2 del Metrobús. Dentro del perímetro circulan autobuses gratuitos entre accesos, de 7:00 a 20:00, para quien muestra su boleto. También existe un servicio privado, Ticket2Ride, con salidas desde zonas como Condesa, Santa Fe e Interlomas; el precio publicado es de 350 pesos por persona, viaje redondo, por cada día de evento.","en":"The promoter's official guide recommends public transport: Metro Line 9, with Velódromo, Ciudad Deportiva and Puebla stations a short walk from the gates, and Metrobús Line 2. Inside the perimeter, free buses run between gates from 7:00 to 20:00 for ticket holders. There is also a private shuttle, Ticket2Ride, departing from areas such as Condesa, Santa Fe and Interlomas; the published price is 350 pesos per person, return, per event day."},{"t":"quote","es":"Los accesos sólo serán permitidos en la sección de tu boleto.","en":"Entry is only allowed through the section on your ticket.","cite":{"es":"Guía oficial MexicoGP","en":"Official MexicoGP guide"}},{"t":"p","es":"Para el regreso, la misma guía sugiere caminar unas calles antes de pedir un auto por aplicación, porque la demanda y los cierres viales se concentran al terminar la carrera.","en":"For the return, the same guide suggests walking a few blocks before ordering a ride-hailing car, because demand and road closures peak when the race ends."},{"t":"h","es":"El sábado, la ciudad también celebra","en":"On Saturday, the city also celebrates"},{"t":"p","es":"El sábado 31 de octubre, el mismo día de la calificación, el Gobierno de la Ciudad de México programó el Gran Desfile de Día de Muertos a las 14:00. Saldrá de Paseo de la Reforma a la altura de la Glorieta de la Diana Cazadora, seguirá hacia el Centro Histórico por la calle 5 de Mayo y llegará a la Plaza de la Constitución, según la información difundida por la administración capitalina y recogida por Expansión y Por Esto. El acceso es gratuito y este año se cumplen diez años de la primera edición. La ruta definitiva y los cierres viales los publica la Secretaría de Seguridad Ciudadana.","en":"On Saturday 31 October, qualifying day, Mexico City's government scheduled the Grand Day of the Dead Parade for 14:00. It will start on Paseo de la Reforma at the Diana Cazadora roundabout, head into the Historic Centre along 5 de Mayo street and finish at the Plaza de la Constitución, according to information released by the city government and reported by Expansión and Por Esto. Admission is free, and this year marks ten years since the first parade. The final route and road closures are published by the city's Public Security Secretariat."},{"t":"note","kind":"analysis","es":"Análisis editorial: el desfile (14:00, centro de la ciudad) y la calificación (15:00, oriente de la ciudad) se cruzan. Quien quiera ambos tendrá que elegir: ver el inicio del desfile en Reforma o llegar con tiempo al autódromo. Con cierres viales en Reforma, el Metro es la apuesta más predecible.","en":"Editorial analysis: the parade (14:00, city centre) and qualifying (15:00, east of the city) overlap. Anyone wanting both will have to choose: see the start of the parade on Reforma or arrive early at the circuit. With road closures on Reforma, the Metro is the most predictable bet."},{"t":"img","image":"img_desfile_muertos","size":"half"},{"t":"h","es":"Lo que no le prometemos","en":"What we do not promise"},{"t":"p","es":"IATOS no vende boletos para el Gran Premio ni tiene acuerdos con el promotor. La venta oficial está en los canales que enlaza MexicoGP. Precios y disponibilidad cambian a diario, por eso no los publicamos aquí: si quiere organizar el fin de semana, Iato puede ayudarle a armar el plan con lo que sí está confirmado.","en":"IATOS does not sell Grand Prix tickets and has no agreement with the promoter. Official sales are on the channels linked by MexicoGP. Prices and availability change daily, so we do not publish them here: if you want to organise the weekend, Iato can help you build the plan with what is actually confirmed."},{"t":"img","image":"img_f1_circuito","size":"full"}]$edi$::jsonb, $edi$[{"kind":"explore_destination","target":"cdmx","label":{"es":"Explorar Ciudad de México en Privé","en":"Explore Mexico City in Privé"}},{"kind":"ask_iato","prompt":{"es":"Quiero organizar el fin de semana del Gran Premio de la Ciudad de México (30 oct–1 nov). Ayúdame con traslados y una cena, sin inventar disponibilidad.","en":"I want to organise the Mexico City Grand Prix weekend (30 Oct–1 Nov). Help me with transport and a dinner, without inventing availability."},"label":{"es":"Organizar el fin de semana con Iato","en":"Plan the weekend with Iato"}},{"kind":"plan_trip","target":"Ciudad de México","label":{"es":"Planear un viaje a la Ciudad de México","en":"Plan a trip to Mexico City"}},{"kind":"official_link","url":"https://www.mexicogp.mx/","label":{"es":"Boletos y guía oficial (MexicoGP)","en":"Tickets and official guide (MexicoGP)"}}]$edi$::jsonb, 20, 'claude', 'pending_review')
