INSERT INTO public.edition_articles (issue_id, slug, section, format, topics, kicker, title, dek, byline, hero_image_id, fact_status, sensitive, fact_date, valid_until, destinations, body, actions, sort_order, drafted_by, status)
VALUES ((SELECT id FROM public.edition_issues WHERE slug = $edi$n01-noviembre-2026$edi$), $edi$merida-guadalajara-mesa-mexicana$edi$, $edi$reportajes$edi$, $edi$feature$edi$, ARRAY[$edi$gastronomia$edi$, $edi$hoteles_y_villas$edi$, $edi$mexico$edi$, $edi$arquitectura_y_diseno$edi$, $edi$viajes_internacionales$edi$]::text[], $edi${"es":"Gastronomía · Hoteles · México","en":"Dining · Hotels · Mexico"}$edi$::jsonb, $edi${"es":"El sureste entra al mapa","en":"The southeast joins the map"}$edi$::jsonb, $edi${"es":"La Guía MICHELIN sumó Jalisco, Puebla y Yucatán en mayo; en septiembre, un hotel de Mérida recibió su primera Llave. Qué cambió y cómo leerlo antes de reservar.","en":"The MICHELIN Guide added Jalisco, Puebla and Yucatán in May; in September, a Mérida hotel received its first Key. What changed and how to read it before booking."}$edi$::jsonb, $edi${"es":"Redacción IATOS Privé","en":"IATOS Privé newsroom"}$edi$::jsonb, (SELECT id FROM public.edition_images WHERE key = $edi$img_merida_catedral$edi$), $edi$mixed$edi$, false, $edi$2026-09-18$edi$::date, NULL, ARRAY[$edi$merida$edi$, $edi$guadalajara$edi$, $edi$cdmx$edi$]::text[], $edi$[{"t":"p","es":"El miércoles 20 de mayo de 2026, en Guadalajara, la Guía MICHELIN presentó su selección mexicana con tres estados que no estaban en el mapa: Jalisco, Puebla y Yucatán. La noche dejó siete restaurantes con su primera estrella, según el recuento de El Restaurante, coincidente con el de Riviera Maya News.","en":"On Wednesday 20 May 2026, in Guadalajara, the MICHELIN Guide presented its Mexican selection with three states that were not on the map: Jalisco, Puebla and Yucatán. The night left seven restaurants with their first star, according to El Restaurante's count, which matches Riviera Maya News."},{"t":"facts","title":{"es":"Primeras estrellas de 2026","en":"First stars of 2026"},"items":[{"label":{"es":"Mérida","en":"Mérida"},"value":{"es":"Huniik y la barra de Huniik (chef Roberto Solís)","en":"Huniik and the Huniik bar (chef Roberto Solís)"}},{"label":{"es":"Chocholá, Yucatán","en":"Chocholá, Yucatán"},"value":{"es":"Ixi'im (chef Luis Ronzón)","en":"Ixi'im (chef Luis Ronzón)"}},{"label":{"es":"Guadalajara","en":"Guadalajara"},"value":{"es":"Alcalde (Paco Ruano) · Xokol (Óscar Segundo y Xrysw Ruelas)","en":"Alcalde (Paco Ruano) · Xokol (Óscar Segundo and Xrysw Ruelas)"}},{"label":{"es":"Ciudad de México","en":"Mexico City"},"value":{"es":"Gaba (chef Víctor Toriz) · La Once Mil","en":"Gaba (chef Víctor Toriz) · La Once Mil"}}]},{"t":"p","es":"En la cima no hubo cambios: Pujol, de Enrique Olvera, y Quintonil, de Jorge Vallejo, ambos en la Ciudad de México, conservaron sus dos estrellas. Xokol e Ixi'im recibieron además una Estrella Verde, la distinción que la guía reserva a prácticas sostenibles, igual que Damiana, en el Valle de Guadalupe.","en":"At the top nothing changed: Enrique Olvera's Pujol and Jorge Vallejo's Quintonil, both in Mexico City, kept their two stars. Xokol and Ixi'im also received a Green Star, the distinction the guide reserves for sustainable practices, as did Damiana in the Valle de Guadalupe."},{"t":"note","kind":"context","es":"Los medios no coinciden en el total nacional de restaurantes con estrella después de la ceremonia; por eso no lo publicamos. Consulte la selección vigente en el sitio oficial de la guía.","en":"Outlets disagree on the national total of starred restaurants after the ceremony, so we do not publish it. Check the current selection on the guide's official site."},{"t":"quote","es":"Una estrella reconoce una cocina; el viaje se decide por la ciudad entera.","en":"A star recognises a kitchen; the trip is decided by the whole city."},{"t":"h","es":"La Llave de Mérida","en":"Mérida's Key"},{"t":"p","es":"Cuatro meses después, el 18 de septiembre, Michelin publicó su selección mundial de hoteles con Llaves para 2026: 470 incorporaciones en 79 destinos y un total de 2,832 hoteles, de los cuales 155 tienen tres Llaves. En su comunicado, la compañía destaca en México a Hotel Sevilla, en Mérida, que recibe su primera Llave por la restauración creativa de un edificio histórico.","en":"Four months later, on 18 September, Michelin published its worldwide 2026 hotel Key selection: 470 additions across 79 destinations and 2,832 hotels in total, 155 of them with three Keys. In its press release, the company singles out Hotel Sevilla in Mérida, which receives its first Key for the creative restoration of a historic building."},{"t":"p","es":"En el continente, la única propiedad nueva con tres Llaves fue Nekajui, a Ritz-Carlton Reserve, en Costa Rica, que subió desde dos, según el mismo comunicado y la cobertura de Outlook Traveller.","en":"In the Americas, the only new three-Key property was Nekajui, a Ritz-Carlton Reserve, in Costa Rica, promoted from two, according to the same release and Outlook Traveller's coverage."},{"t":"img","image":"img_chile_nogada","size":"half"},{"t":"note","kind":"analysis","es":"Lectura editorial: en cinco meses, Mérida sumó estrellas para Huniik y una primera Llave hotelera. Para un viaje de fin de semana, la ciudad ofrece hoy una combinación de mesa y hotel reconocidos que antes había que buscar en otras capitales.","en":"Editorial reading: in five months, Mérida gained stars for Huniik and a first hotel Key. For a weekend trip, the city now offers a combination of recognised table and hotel that used to require other capitals."},{"t":"h","es":"Antes de reservar","en":"Before booking"},{"t":"p","es":"Una distinción no garantiza mesa ni habitación. Reserve por los canales oficiales de cada restaurante y hotel; IATOS no tiene acuerdos con ninguno de los establecimientos mencionados. Si quiere armar el viaje, en Privé puede explorar Mérida y Guadalajara y pedirle a Iato que verifique el método de reserva de cada lugar.","en":"A distinction does not guarantee a table or a room. Book through each restaurant's and hotel's official channels; IATOS has no agreement with any of the establishments mentioned. To build the trip, you can explore Mérida and Guadalajara in Privé and ask Iato to check each place's booking method."}]$edi$::jsonb, $edi$[{"kind":"explore_destination","target":"merida","label":{"es":"Explorar Mérida en Privé","en":"Explore Mérida in Privé"}},{"kind":"explore_destination","target":"guadalajara","label":{"es":"Explorar Guadalajara en Privé","en":"Explore Guadalajara in Privé"}},{"kind":"explore_universe","target":"the_table","label":{"es":"THE TABLE · cocina con fuentes","en":"THE TABLE · sourced dining"}},{"kind":"restaurants","target":"Mérida","label":{"es":"Buscar restaurante y cómo reservar en Mérida","en":"Find a restaurant and how to book in Mérida"}},{"kind":"hotels","target":"Mérida","label":{"es":"Comparar hoteles verificables en Mérida","en":"Compare verifiable hotels in Mérida"}}]$edi$::jsonb, 30, 'claude', 'pending_review')
ON CONFLICT (slug) DO NOTHING;
