VALUES ((SELECT id FROM public.edition_issues WHERE slug = $edi$n01-noviembre-2026$edi$), $edi$watches-and-wonders-2027$edi$, $edi$agenda$edi$, $edi$short$edi$, ARRAY[$edi$relojes$edi$, $edi$joyeria$edi$, $edi$eventos_internacionales$edi$, $edi$moda$edi$]::text[], $edi${"es":"Relojería · Ginebra","en":"Watchmaking · Geneva"}$edi$::jsonb, $edi${"es":"Ginebra ya marcó la hora","en":"Geneva has set the time"}$edi$::jsonb, $edi${"es":"Watches and Wonders 2027 será del 5 al 11 de abril, con 75 marcas y 13 debutantes.","en":"Watches and Wonders 2027 runs 5–11 April, with 75 brands and 13 newcomers."}$edi$::jsonb, $edi${"es":"Redacción IATOS Privé","en":"IATOS Privé newsroom"}$edi$::jsonb, (SELECT id FROM public.edition_images WHERE key = $edi$img_reloj$edi$), $edi$verified_facts$edi$, false, $edi$2026-06-23$edi$::date, $edi$2027-04-11$edi$::date, ARRAY[$edi$ginebra$edi$]::text[], $edi$[{"t":"p","es":"El salón relojero más grande de Ginebra ya tiene fecha: del 5 al 11 de abril de 2027, en Palexpo. El sitio oficial enumera 75 marcas expositoras, 13 de ellas nuevas. Entre las incorporaciones anunciadas en junio están Breitling, Gallet y Universal Genève —el trío que encabeza Georges Kern— y la joyera italiana Damiani, según Watches by SJX.","en":"Geneva's largest watch fair has its dates: 5 to 11 April 2027, at Palexpo. The official site lists 75 exhibiting brands, 13 of them new. Newcomers announced in June include Breitling, Gallet and Universal Genève —the trio led by Georges Kern— and Italian jeweller Damiani, according to Watches by SJX."},{"t":"p","es":"El formato se mantiene: de lunes a jueves, jornadas para profesionales con invitación; viernes, sábado y domingo, abierto al público con boleto. Las entradas se consultan en el sitio oficial.","en":"The format stays the same: Monday to Thursday for invited trade visitors; Friday to Sunday open to the public with a ticket. Check tickets on the official site."}]$edi$::jsonb, $edi$[{"kind":"explore_destination","target":"ginebra","label":{"es":"Explorar Ginebra en Privé","en":"Explore Geneva in Privé"}},{"kind":"official_link","url":"https://www.watchesandwonders.com/","label":{"es":"Sitio oficial de Watches and Wonders","en":"Watches and Wonders official site"}}]$edi$::jsonb, 50, 'claude', 'pending_review')
ON CONFLICT (slug) DO NOTHING;
