VALUES ((SELECT id FROM public.edition_issues WHERE slug = $edi$n01-noviembre-2026$edi$), $edi$art-basel-miami-beach-2026$edi$, $edi$agenda$edi$, $edi$short$edi$, ARRAY[$edi$arte$edi$, $edi$cultura$edi$, $edi$eventos_internacionales$edi$, $edi$arquitectura_y_diseno$edi$]::text[], $edi${"es":"Arte · Miami Beach","en":"Art · Miami Beach"}$edi$::jsonb, $edi${"es":"Diciembre en Miami Beach","en":"December in Miami Beach"}$edi$::jsonb, $edi${"es":"Art Basel Miami Beach abre al público del 4 al 6 de diciembre de 2026.","en":"Art Basel Miami Beach opens to the public from 4 to 6 December 2026."}$edi$::jsonb, $edi${"es":"Redacción IATOS Privé","en":"IATOS Privé newsroom"}$edi$::jsonb, (SELECT id FROM public.edition_images WHERE key = $edi$img_miami_ocean_drive$edi$), $edi$verified_facts$edi$, false, $edi$2026-10-16$edi$::date, $edi$2026-12-06$edi$::date, ARRAY[$edi$miami-beach$edi$]::text[], $edi$[{"t":"p","es":"La edición de Art Basel en Miami Beach será del 4 al 6 de diciembre de 2026, según el sitio oficial de la feria. Las jornadas públicas, de viernes a domingo, se celebran en el Miami Beach Convention Center, de 11:00 a 18:00, y los días por invitación comienzan el 2 de diciembre, según la guía publicada por Miami Living.","en":"Art Basel's Miami Beach edition runs from 4 to 6 December 2026, according to the fair's official site. The public days, Friday to Sunday, take place at the Miami Beach Convention Center from 11:00 to 18:00, and invitation-only days begin on 2 December, according to the guide published by Miami Living."},{"t":"p","es":"Consulte entradas y condiciones de acceso en el sitio oficial de Art Basel. IATOS no tiene acuerdo con la feria ni ofrece acceso preferente.","en":"Check tickets and access conditions on Art Basel's official site. IATOS has no agreement with the fair and offers no preferential access."}]$edi$::jsonb, $edi$[{"kind":"explore_destination","target":"miami-beach","label":{"es":"Explorar Miami Beach en Privé","en":"Explore Miami Beach in Privé"}},{"kind":"explore_universe","target":"culture_access","label":{"es":"CULTURE & ACCESS","en":"CULTURE & ACCESS"}},{"kind":"official_link","url":"https://www.artbasel.com/miami-beach","label":{"es":"Sitio oficial de Art Basel Miami Beach","en":"Art Basel Miami Beach official site"}}]$edi$::jsonb, 60, 'claude', 'pending_review')
