VALUES ((SELECT id FROM public.edition_issues WHERE slug = $edi$n01-noviembre-2026$edi$), $edi$pga-tour-los-cabos-2026$edi$, $edi$agenda$edi$, $edi$short$edi$, ARRAY[$edi$golf$edi$, $edi$deportes$edi$, $edi$mexico$edi$]::text[], $edi${"es":"Golf · Los Cabos","en":"Golf · Los Cabos"}$edi$::jsonb, $edi${"es":"El PGA Tour vuelve a Los Cabos","en":"The PGA Tour returns to Los Cabos"}$edi$::jsonb, $edi${"es":"El World Wide Technology Championship se juega del 5 al 8 de noviembre en El Cardonal at Diamante.","en":"The World Wide Technology Championship is played 5–8 November at El Cardonal at Diamante."}$edi$::jsonb, $edi${"es":"Redacción IATOS Privé","en":"IATOS Privé newsroom"}$edi$::jsonb, (SELECT id FROM public.edition_images WHERE key = $edi$img_cabo_costa$edi$), $edi$verified_facts$edi$, false, $edi$2026-10-22$edi$::date, $edi$2026-11-08$edi$::date, ARRAY[$edi$los-cabos$edi$]::text[], $edi$[{"t":"p","es":"El circuito estadounidense regresa a Baja California Sur del 5 al 8 de noviembre de 2026 con el World Wide Technology Championship, en el campo El Cardonal at Diamante, en Los Cabos. La bolsa anunciada por el PGA Tour es de 6 millones de dólares. El campeón defensor es Ben Griffin, que en 2025 terminó con −29 y un total de 259 golpes.","en":"The US tour returns to Baja California Sur from 5 to 8 November 2026 with the World Wide Technology Championship, on the El Cardonal at Diamante course in Los Cabos. The purse announced by the PGA Tour is 6 million dollars. The defending champion is Ben Griffin, who finished at −29 with a 259 total in 2025."},{"t":"img","image":"img_golf","size":"half"},{"t":"p","es":"Para quien quiera combinarlo con unos días frente al mar, Los Cabos está en la sección de destinos de Privé, con experiencias verificadas y la colección SPORT & LEISURE.","en":"For anyone combining it with a few days by the sea, Los Cabos is in Privé's destinations, with verified experiences and the SPORT & LEISURE collection."}]$edi$::jsonb, $edi$[{"kind":"explore_destination","target":"los-cabos","label":{"es":"Explorar Los Cabos en Privé","en":"Explore Los Cabos in Privé"}},{"kind":"explore_universe","target":"sport_leisure","label":{"es":"SPORT & LEISURE","en":"SPORT & LEISURE"}},{"kind":"official_link","url":"https://www.pgatour.com/tournaments/2026/world-wide-technology-championship/R2026457/overview","label":{"es":"Ficha oficial del torneo (PGA Tour)","en":"Official tournament page (PGA Tour)"}}]$edi$::jsonb, 70, 'claude', 'pending_review')
