INSERT INTO public.edition_articles (issue_id, slug, section, format, topics, kicker, title, dek, byline, hero_image_id, fact_status, sensitive, fact_date, valid_until, destinations, body, actions, sort_order, drafted_by, status)
VALUES ((SELECT id FROM public.edition_issues WHERE slug = $edi$n01-noviembre-2026$edi$), $edi$ue-ia-alto-riesgo-2027$edi$, $edi$explicadores$edi$, $edi$explainer$edi$, ARRAY[$edi$inteligencia_artificial$edi$, $edi$tecnologia$edi$, $edi$negocios$edi$, $edi$noticias_mundiales$edi$]::text[], $edi${"es":"Inteligencia artificial · Explicador","en":"Artificial intelligence · Explainer"}$edi$::jsonb, $edi${"es":"Bruselas mueve el reloj de la IA de alto riesgo","en":"Brussels moves the clock on high-risk AI"}$edi$::jsonb, $edi${"es":"El llamado «Omnibus» de IA, en vigor desde el 27 de julio, aplazó a diciembre de 2027 las obligaciones para los sistemas de alto riesgo. Qué cambió y qué no.","en":"The so-called AI Omnibus, in force since 27 July, pushed obligations for high-risk systems to December 2027. What changed and what did not."}$edi$::jsonb, $edi${"es":"Redacción IATOS Privé","en":"IATOS Privé newsroom"}$edi$::jsonb, NULL, $edi$mixed$edi$, false, $edi$2026-07-27$edi$::date, NULL, ARRAY[]::text[], $edi$[{"t":"p","es":"La Unión Europea reformó el calendario de su Ley de Inteligencia Artificial. El Reglamento (UE) 2026/1744, conocido como Omnibus de IA, se publicó en el Diario Oficial el 24 de julio de 2026 y entró en vigor el 27 de julio, según el análisis del despacho K&L Gates. Había nacido de un acuerdo provisional entre Parlamento y Consejo el 7 de mayo.","en":"The European Union has reshaped the timetable of its Artificial Intelligence Act. Regulation (EU) 2026/1744, known as the AI Omnibus, was published in the Official Journal on 24 July 2026 and entered into force on 27 July, according to an analysis by law firm K&L Gates. It stemmed from a provisional agreement between Parliament and Council on 7 May."},{"t":"facts","title":{"es":"Las fechas que cambiaron","en":"The dates that changed"},"items":[{"label":{"es":"Alto riesgo «autónomo» (Anexo III: empleo, educación, crédito…)","en":"Stand-alone high-risk (Annex III: employment, education, credit…)"},"value":{"es":"Del 2 ago 2026 al 2 dic 2027","en":"From 2 Aug 2026 to 2 Dec 2027"}},{"label":{"es":"IA integrada en productos regulados (Anexo I)","en":"AI embedded in regulated products (Annex I)"},"value":{"es":"Hasta el 2 ago 2028","en":"Until 2 Aug 2028"}},{"label":{"es":"Marcado de contenido generado por IA","en":"Marking AI-generated content"},"value":{"es":"Gracia hasta el 2 dic 2026, solo para sistemas en el mercado antes del 2 ago 2026","en":"Grace until 2 Dec 2026, only for systems on the market before 2 Aug 2026"}}]},{"t":"p","es":"Lo que no se aplazó, según K&L Gates: los deberes de transparencia siguen aplicando desde el 2 de agosto de 2026, con la única gracia descrita arriba para el marcado de contenido de sistemas que ya estaban en el mercado.","en":"What was not postponed, according to K&L Gates: transparency duties continue to apply from 2 August 2026, with the only grace period described above for marking content from systems already on the market."},{"t":"note","kind":"analysis","es":"Por qué importa fuera de Europa: la ley alcanza a empresas de cualquier país que ofrezcan sistemas de IA en la Unión. Para una empresa mexicana con clientes europeos, el aplazamiento da tiempo, no una exención.","en":"Why it matters outside Europe: the law reaches companies from any country that offer AI systems in the Union. For a Mexican company with European clients, the delay buys time, not an exemption."},{"t":"note","kind":"disclaimer","es":"Información general, no asesoría jurídica. Las fechas provienen de análisis de despachos; el texto oficial está en EUR-Lex.","en":"General information, not legal advice. Dates come from law-firm analyses; the official text is on EUR-Lex."}]$edi$::jsonb, $edi$[]$edi$::jsonb, 90, 'claude', 'pending_review')
ON CONFLICT (slug) DO NOTHING;
