VALUES ((SELECT id FROM public.edition_issues WHERE slug = $edi$n01-noviembre-2026$edi$), $edi$brief-nobel-economia-2026$edi$, $edi$world_brief$edi$, $edi$brief$edi$, ARRAY[$edi$noticias_mundiales$edi$, $edi$finanzas_y_mercados$edi$, $edi$negocios$edi$]::text[], $edi${"es":"Ciencia económica","en":"Economic science"}$edi$::jsonb, $edi${"es":"Nobel de Economía para Robert E. Hall y Michael Woodford","en":"Economics Nobel for Robert E. Hall and Michael Woodford"}$edi$::jsonb, $edi${"es":"12 de octubre de 2026","en":"12 October 2026"}$edi$::jsonb, $edi${"es":"The World Brief","en":"The World Brief"}$edi$::jsonb, NULL, $edi$verified_facts$edi$, false, $edi$2026-10-12$edi$::date, $edi$2026-12-31$edi$::date, ARRAY[]::text[], $edi$[{"t":"p","es":"Hecho: el premio de Ciencias Económicas en memoria de Alfred Nobel 2026 fue para los estadounidenses Robert E. Hall y Michael Woodford «por los fundamentos microeconómicos de la estabilización macroeconómica». El premio es de 12 millones de coronas suecas.","en":"Fact: the 2026 Prize in Economic Sciences in Memory of Alfred Nobel went to Americans Robert E. Hall and Michael Woodford 'for microeconomic foundations of macroeconomic stabilisation'. The prize is worth 12 million Swedish kronor."},{"t":"note","kind":"analysis","es":"Por qué importa: sus modelos están detrás de cómo los bancos centrales calibran tasas para suavizar ciclos. Ver el explicador sobre Banxico en este número.","en":"Why it matters: their models underpin how central banks calibrate rates to smooth cycles. See the Banxico explainer in this issue."}]$edi$::jsonb, $edi$[]$edi$::jsonb, 100, 'claude', 'pending_review')
