VALUES ((SELECT id FROM public.edition_issues WHERE slug = $edi$n01-noviembre-2026$edi$), $edi$brief-lvmh-tercer-trimestre-2026$edi$, $edi$world_brief$edi$, $edi$brief$edi$, ARRAY[$edi$noticias_mundiales$edi$, $edi$finanzas_y_mercados$edi$, $edi$moda$edi$, $edi$relojes$edi$, $edi$joyeria$edi$, $edi$negocios$edi$]::text[], $edi${"es":"Industria del lujo","en":"Luxury industry"}$edi$::jsonb, $edi${"es":"LVMH crece 1% orgánico en el tercer trimestre; China pesa en la moda","en":"LVMH grows 1% organically in Q3; China weighs on fashion"}$edi$::jsonb, $edi${"es":"12 de octubre de 2026","en":"12 October 2026"}$edi$::jsonb, $edi${"es":"The World Brief","en":"The World Brief"}$edi$::jsonb, NULL, $edi$verified_facts$edi$, false, $edi$2026-10-12$edi$::date, $edi$2027-01-31$edi$::date, ARRAY[]::text[], $edi$[{"t":"p","es":"Hecho: LVMH reportó ingresos de 57,100 millones de euros en los primeros nueve meses de 2026 (−2% reportado, +2% orgánico). En el tercer trimestre el crecimiento orgánico fue de 1%: Moda y Marroquinería cayó 5%, mientras Relojes y Joyería y Vinos y Licores subieron 6% y Distribución Selectiva 8%. La empresa atribuye la moderación a un entorno menos dinámico en China.","en":"Fact: LVMH reported revenue of 57.1 billion euros for the first nine months of 2026 (−2% reported, +2% organic). Third-quarter organic growth was 1%: Fashion & Leather Goods fell 5%, while Watches & Jewelry and Wines & Spirits rose 6% and Selective Retailing 8%. The company attributes the slowdown to a less buoyant environment in China."},{"t":"note","kind":"disclaimer","es":"Información, no recomendación sobre valores.","en":"Information, not a securities recommendation."}]$edi$::jsonb, $edi$[]$edi$::jsonb, 110, 'claude', 'pending_review')
