VALUES ((SELECT id FROM public.edition_issues WHERE slug = $edi$n01-noviembre-2026$edi$), $edi$brief-inegi-viajeros-agosto-2026$edi$, $edi$world_brief$edi$, $edi$brief$edi$, ARRAY[$edi$mexico$edi$, $edi$viajes_internacionales$edi$, $edi$noticias_mundiales$edi$, $edi$negocios$edi$]::text[], $edi${"es":"Turismo","en":"Tourism"}$edi$::jsonb, $edi${"es":"México recibió 7.99 millones de viajeros internacionales en agosto","en":"Mexico received 7.99 million international travellers in August"}$edi$::jsonb, $edi${"es":"14 de octubre de 2026","en":"14 October 2026"}$edi$::jsonb, $edi${"es":"The World Brief","en":"The World Brief"}$edi$::jsonb, NULL, $edi$verified_facts$edi$, false, $edi$2026-10-14$edi$::date, $edi$2026-11-12$edi$::date, ARRAY[]::text[], $edi$[{"t":"p","es":"Hecho: según la Encuesta de Viajeros Internacionales del INEGI, en agosto de 2026 entraron al país 7,985,700 viajeros internacionales, 1.3% más que un año antes. De ellos, 3,768,784 fueron turistas que pernoctaron (−0.5%). El gasto total creció 7.0% y el gasto medio 5.6%. Son cifras preliminares; la próxima publicación es el 12 de noviembre.","en":"Fact: according to INEGI's International Travellers Survey, 7,985,700 international travellers entered Mexico in August 2026, 1.3% more than a year earlier. Of them, 3,768,784 were overnight tourists (−0.5%). Total spending grew 7.0% and average spending 5.6%. Figures are preliminary; the next release is on 12 November."}]$edi$::jsonb, $edi$[]$edi$::jsonb, 120, 'claude', 'pending_review')
ON CONFLICT (slug) DO NOTHING;
