VALUES ((SELECT id FROM public.edition_issues WHERE slug = $edi$n01-noviembre-2026$edi$), $edi$brief-banxico-24-septiembre$edi$, $edi$world_brief$edi$, $edi$brief$edi$, ARRAY[$edi$finanzas_y_mercados$edi$, $edi$mexico$edi$, $edi$negocios$edi$]::text[], $edi${"es":"Economía","en":"Economy"}$edi$::jsonb, $edi${"es":"Banxico mantiene su tasa en 6.50% por tercera reunión","en":"Banxico holds its rate at 6.50% for a third meeting"}$edi$::jsonb, $edi${"es":"24 de septiembre de 2026","en":"24 September 2026"}$edi$::jsonb, $edi${"es":"The World Brief","en":"The World Brief"}$edi$::jsonb, NULL, $edi$verified_facts$edi$, true, $edi$2026-09-24$edi$::date, $edi$2026-11-05$edi$::date, ARRAY[]::text[], $edi$[{"t":"p","es":"Hecho: el 24 de septiembre, la Junta de Gobierno del Banco de México mantuvo sin cambio en 6.50% el objetivo para la tasa interbancaria a un día, igual que en junio y agosto. El siguiente anuncio está programado para el 5 de noviembre a las 13:00.","en":"Fact: on 24 September, the Bank of Mexico's Governing Board kept the overnight interbank target rate unchanged at 6.50%, as in June and August. The next announcement is scheduled for 5 November at 13:00."},{"t":"note","kind":"disclaimer","es":"Información, no asesoría de inversión.","en":"Information, not investment advice."}]$edi$::jsonb, $edi$[]$edi$::jsonb, 130, 'claude', 'pending_review')
