VALUES ((SELECT id FROM public.edition_issues WHERE slug = $edi$n01-noviembre-2026$edi$), $edi$brief-delta-aeromexico-tribunal$edi$, $edi$world_brief$edi$, $edi$brief$edi$, ARRAY[$edi$viajes_internacionales$edi$, $edi$negocios$edi$, $edi$mexico$edi$, $edi$noticias_mundiales$edi$]::text[], $edi${"es":"Aviación","en":"Aviation"}$edi$::jsonb, $edi${"es":"Un tribunal de EE. UU. mantiene viva la alianza Delta–Aeroméxico","en":"US court keeps the Delta–Aeroméxico alliance alive"}$edi$::jsonb, $edi${"es":"21 de agosto de 2026","en":"21 August 2026"}$edi$::jsonb, $edi${"es":"The World Brief","en":"The World Brief"}$edi$::jsonb, NULL, $edi$verified_facts$edi$, false, $edi$2026-08-21$edi$::date, $edi$2026-12-31$edi$::date, ARRAY[]::text[], $edi$[{"t":"p","es":"Hecho: el Tribunal de Apelaciones del 11.º Circuito anuló la orden del Departamento de Transporte de EE. UU. que ponía fin a la aprobación de la empresa conjunta entre Delta y Aeroméxico, que puede seguir operando. Según InsideFlyer, el tribunal señaló que el DOT no explicó por qué redujo su análisis de 1,687 pares de ciudades a los vuelos de la Ciudad de México; el DOT aún puede volver a actuar con un caso nuevo.","en":"Fact: the US Court of Appeals for the 11th Circuit vacated the Department of Transportation's order ending its approval of the Delta–Aeroméxico joint venture, which can keep operating. According to InsideFlyer, the court noted the DOT did not explain why it narrowed its analysis from 1,687 city pairs to Mexico City flights; the DOT may still act again with a new case."},{"t":"note","kind":"context","es":"Una de las fuentes es el comunicado de Delta, parte interesada.","en":"One of the sources is Delta's press release, an interested party."}]$edi$::jsonb, $edi$[]$edi$::jsonb, 140, 'claude', 'pending_review')
ON CONFLICT (slug) DO NOTHING;
