INSERT INTO public.edition_articles (issue_id, slug, section, format, topics, kicker, title, dek, byline, hero_image_id, fact_status, sensitive, fact_date, valid_until, destinations, body, actions, sort_order, drafted_by, status)
VALUES ((SELECT id FROM public.edition_issues WHERE slug = $edi$n01-noviembre-2026$edi$), $edi$brief-desfile-dia-de-muertos-2026$edi$, $edi$world_brief$edi$, $edi$brief$edi$, ARRAY[$edi$mexico$edi$, $edi$cultura$edi$, $edi$eventos_internacionales$edi$]::text[], $edi${"es":"Cultura · Ciudad de México","en":"Culture · Mexico City"}$edi$::jsonb, $edi${"es":"Desfile de Día de Muertos: sábado 31 de octubre, 14:00","en":"Day of the Dead parade: Saturday 31 October, 14:00"}$edi$::jsonb, $edi${"es":"14 de octubre de 2026","en":"14 October 2026"}$edi$::jsonb, $edi${"es":"The World Brief","en":"The World Brief"}$edi$::jsonb, NULL, $edi$verified_facts$edi$, false, $edi$2026-10-14$edi$::date, $edi$2026-10-31$edi$::date, ARRAY[$edi$cdmx$edi$]::text[], $edi$[{"t":"p","es":"Hecho: el Gran Desfile de Día de Muertos de la Ciudad de México será el sábado 31 de octubre a las 14:00, de la Diana Cazadora en Paseo de la Reforma al Zócalo, con entrada libre. Se cumplen diez años de la primera edición.","en":"Fact: Mexico City's Grand Day of the Dead Parade will be on Saturday 31 October at 14:00, from the Diana Cazadora on Paseo de la Reforma to the Zócalo, free of charge. It is ten years since the first edition."}]$edi$::jsonb, $edi$[{"kind":"explore_destination","target":"cdmx","label":{"es":"Explorar Ciudad de México en Privé","en":"Explore Mexico City in Privé"}}]$edi$::jsonb, 150, 'claude', 'pending_review')
ON CONFLICT (slug) DO NOTHING;
