-- Tiempo de lectura (mismo cálculo que el panel: 220 palabras por minuto)
UPDATE public.edition_articles SET word_count = public.edition_body_words(body), reading_minutes = greatest(1, ceil(public.edition_body_words(body) / 220.0)::int)
WHERE issue_id = (SELECT id FROM public.edition_issues WHERE slug = $edi$n01-noviembre-2026$edi$) AND word_count = 0;

-- Bitácora: una fila 'seed' por pieza (solo la primera vez)
INSERT INTO public.edition_reviews (entity, entity_key, action, note)
SELECT 'article', a.slug, 'seed', 'Borrador asistido por IA (Claude) a partir de fuentes registradas; pendiente de revisión editorial.'
  FROM public.edition_articles a WHERE a.issue_id = (SELECT id FROM public.edition_issues WHERE slug = $edi$n01-noviembre-2026$edi$)
   AND NOT EXISTS (SELECT 1 FROM public.edition_reviews r WHERE r.entity = 'article' AND r.entity_key = a.slug AND r.action = 'seed');
INSERT INTO public.edition_reviews (entity, entity_key, action, note)
SELECT 'issue', $edi$n01-noviembre-2026$edi$, 'seed', 'Número sembrado en pending_review.' WHERE NOT EXISTS (SELECT 1 FROM public.edition_reviews r WHERE r.entity = 'issue' AND r.entity_key = $edi$n01-noviembre-2026$edi$ AND r.action = 'seed');
